function restriction_faithful(rho, g1, g2):
    if column_rank(rho) != num_columns(rho):
        error 'restriction not injective'
    if rho * g1 != rho * g2:
        error 'hypothesis rho.g1 = rho.g2 fails'
    return (g1 == g2)        # forced by injectivity of rho
